const version=new URL(self.location.href).searchParams.get('v')||'';importScripts(...['engine.js','eggby-tools.js','unit-tools.js'].map(f=>'/'+f+(version?'?v='+version:'')));
self.onmessage=async({data})=>{try{const target=CoopTargets.TARGET_BY_ID.get(data.target);if(!target||target.mode!==data.mode)throw Error('계산 대상을 확인하세요.');const input={...data,targetData:target};if(data.kind==='top'){const result=await CoopUnitTools.top(input,CoopEngine,CoopData,CoopEggby,p=>postMessage({id:data.id,kind:'top-progress',...p}));for(const r of result.rankings){const checked=CoopUnitTools.row(input,r.gems,CoopEngine,CoopData,CoopEggby,true);r.dps=checked.dps;r.formula=checked.formula;}result.rankings.sort(CoopUnitTools.compareDps);postMessage({id:data.id,kind:'top',...result});return;}if(data.kind==='recommend'){postMessage({id:data.id,kind:data.kind,...CoopUnitTools.recommend(input,CoopEngine,CoopData,CoopEggby)});return;}if(!Array.isArray(data.sets)||data.sets.length<1||data.sets.length>3)throw Error('비교 조합은 1~3개입니다.');postMessage({id:data.id,rows:data.sets.map(g=>CoopUnitTools.row(input,g,CoopEngine,CoopData,CoopEggby,true))});}catch(e){postMessage({id:data.id,error:e.message});}};
